inventory.wl.source:
$HistoryLength=0;
base="/common/dev/amflow/target/diffexp-oracle/mg5-audit/selected-grid-files";
out="/common/dev/amflow/target/gg-hg-inventory";
str[x_]:=ToString[x,InputForm];sha[f_]:=IntegerString[FileHash[f,"SHA256"],16,64];
records={};
Do[
f=FileNameJoin[{base,fam,"atilde_"<>fam<>".txt"}];a=Get[f];n=Length[a];
letters=DeleteDuplicates[Cases[a,Log[z_]:>z,Infinity]];
logs=Log/@letters;markers=Table[Unique["l"],Length[letters]];
polynomial=a/.Thread[logs->markers];
constantPart=polynomial/.Thread[markers->0];
matrices=Table[Map[Coefficient[#,markers[[k]]]&,polynomial,{2}],{k,Length[markers]}];
linearQ=TrueQ[Expand[polynomial-Sum[matrices[[k]] markers[[k]],{k,Length[markers]}]]===ConstantArray[0,{n,n}]];
constantQ=FreeQ[matrices,s|t|u|b|_Log];
roots=DeleteDuplicates[Cases[letters,Power[z_,q_Rational]/;Denominator[q]>1:>{z,q},Infinity]];
rootbases=DeleteDuplicates[First/@roots];
nonzero=Count[Flatten[a],Except[0]];
bcfile=FileNameJoin[{base,fam,"BClist","BClist_"<>fam<>"_p1011194946161727751.txt"}];bc=Get[bcfile];
precfile=FileNameJoin[{base,fam,"preCan_functions_"<>fam<>".txt"}];pre=Get[precfile];
rec=<|"family"->fam,"dimension"->n,"nonzero_connection_entries"->nonzero,"letter_count"->Length[letters],"letters"->(str/@letters),"root_powers"->Map[str,roots,{2}],"syntactically_distinct_root_base_count"->Length[rootbases],"root_bases"->(str/@rootbases),"linear_log_decomposition"->linearQ,"constant_exact_coefficient_matrices"->constantQ,"constant_remainder_zero"->And@@(#===0&/@Flatten[constantPart]),"matrix_sha256"->sha[f],"source_boundary"-><|"file"->bcfile,"sha256"->sha[bcfile],"point"->(str/@({vv[1],vv[2],vv[3]}/.bc[[1]])),"shape"->Dimensions[bc[[2]]],"delta"->str[bc[[3]]],"minimum_component_precision"->str[Min[Precision/@Flatten[bc[[2]]]]],"minimum_component_accuracy"->str[Min[Accuracy/@Flatten[bc[[2]]]]]|>,"precanonical_map"-><|"sha256"->sha[precfile],"expressions"->Length[pre],"heads"->(str/@DeleteDuplicates[Cases[pre,z_[___]:>z,Infinity]])|>|>;
AppendTo[records,rec];
Export[FileNameJoin[{out,fam<>"-canonical.json"}],<|"family"->fam,"dimension"->n,"variables"->{"s","t","b"},"dependent"->"u=b-s-t","letters"->(str/@letters),"root_bases"->(str/@rootbases),"matrices"->Table[<|"letter"->k,"entries"->Cases[MapIndexed[If[#1===0,Nothing,{#2[[1]],#2[[2]],str[#1]}]&,matrices[[k]],{2}],{_Integer,_Integer,_String},Infinity]|>,{k,Length[letters]}],"matrix_sha256"->sha[f]|>,"RawJSON"];
Print[fam," dimension=",n," letters=",Length[letters]," roots=",Length[rootbases]," exactconstant=",constantQ," linear=",linearQ],
{fam,{"Planar_EW1","NP_EW1"}}];
fffile="/common/dev/mg5_higgs_ew_plugin/ComputationFormFacGGHGEW/mathematicaRoutines/FFlist.txt";ff=Get[fffile];
ffrecords=Table[uses=DeleteDuplicates[Cases[ff,head[i_Integer,e_Integer,c_List]:>{i,e,c},Infinity]];<|"family"->ToString[head],"unique_uses"->Length[uses],"master_indices"->Sort[DeleteDuplicates[uses[[All,1]]]],"epsilon_orders"->Sort[DeleteDuplicates[uses[[All,2]]]],"permutations"->(str/@DeleteDuplicates[uses[[All,3]]])|>,{head,{canMIPlanar,canMINP}}];
Export[FileNameJoin[{out,"inventory.json"}],<|"source_commit"->"89f64b93d0bdbd8ee90eb85737021189229b034a","families"->records,"form_factors"-><|"count"->Length[ff],"sha256"->sha[fffile],"usage"->ffrecords|>|>,"RawJSON"];
Print["DONE ",ffrecords];Exit[0];

precision_inventory.wl.source:
$HistoryLength=0;
base="/common/dev/amflow/target/diffexp-oracle/mg5-audit/selected-grid-files";out="/common/dev/amflow/target/gg-hg-inventory";str[x_]:=ToString[x,InputForm];
summary={};
Do[
a=Get[FileNameJoin[{base,fam,"atilde_"<>fam<>".txt"}]];roots=DeleteDuplicates[Cases[a,Power[z_,q_Rational]/;Denominator[q]>1:>Expand[z],Infinity]];
f=FileNameJoin[{base,fam,"BClist","BClist_"<>fam<>"_p1011194946161727751.txt"}];bc=Get[f];values=Flatten[bc[[2]]];inexact=Select[values,Precision[#]=!=Infinity&];nonzero=Select[inexact,!TrueQ[#==0]&];
AppendTo[summary,<|"family"->fam,"normalized_root_bases"->(str/@roots),"normalized_distinct_root_base_count"->Length[roots],"root_signs_at_selected_point"->(str/@N[roots/.{s->vv[1],t->vv[2],b->vv[3]}/.bc[[1]],30]),"number_inexact_components"->Length[inexact],"number_inexact_nonzero_components"->Length[nonzero],"min_component_precision"->str[Min[Precision/@inexact]],"min_component_accuracy"->str[Min[Accuracy/@inexact]],"inherited_delta"->str[bc[[3]]]|>],{fam,{"Planar_EW1","NP_EW1"}}];
ff=Get["/common/dev/mg5_higgs_ew_plugin/ComputationFormFacGGHGEW/mathematicaRoutines/FFlist.txt"];
pin=Get[FileNameJoin[{base,"NP_EW1","BClist","BClist_NP_EW1_p1011194946161727751.txt"}]][[1]];
terms=If[Head[#]===Plus,List@@#,{#}]&/@Expand[ff];
linear=And@@Flatten[Map[Function[z,Length[Cases[z,_canMIPlanar|_canMINP,{0,Infinity}]]==1],terms,{2}]];
coefficientL1=Map[Total[Abs[N[#/.{_canMIPlanar->1,_canMINP->1}/.pin/.ieps0->0,60]]&/@#]&,terms];
If[!linear || !And@@(NumericQ/@coefficientL1),Print["FAIL linear/numeric ",linear];Exit[1]];
Export[FileNameJoin[{out,"precision-inventory.json"}],<|"families"->summary,"form_factor_term_counts"->(Length/@terms),"single_MI_per_additive_term"->linear,"coefficient_L1_at_selected_dimensionless_point"->(str/@coefficientL1),"conservative_assumed_component_error"->"1e-26 at every family/permutation component; actual unavailable permuted source records must be checked before accepting this bound","resulting_unscaled_ff_error_estimates"->(str/@N[10^-26 coefficientL1,40]),"mv_equals_one_loop_measure_error_estimates"->(str/@N[10^-26 coefficientL1/(4Pi)^4,40]),"scope"->"Conditioning diagnostic only: no form factors or permuted target integrals evaluated. For coefficient magnitudes only, ieps0 is taken to0 at this nonsingular point; this does not define the physical sheet for amplitude values. Coefficient norm uses every raw additive term, so repeated MI cancellations can only improve this conservative bound."|>,"RawJSON"];
Print["DONE roots ",summary," ffL1 ",coefficientL1," linear ",linear];Exit[0];
